        ship(manifest, SOURCE, List.of(seal(b1, "S1"), seal(b2, "S2"), seal("BK-GHOST", "S3")), "RS3", 422);
        // 重复封签批次：整单失败
        ship(manifest, SOURCE, List.of(seal(b1, "S1"), seal(b1, "S2")), "RS4", 422);

        // 全部批次保持发运前状态，无发运事件，移交单仍 CREATED
        assertEquals("QUARANTINED", statusOf(b1));
